#include <iostream>
#include <regex>
#include <string>

int main() {
    std::string input = "Hello, World!";
    std::regex pattern(R"(Hello\,\sWorld\!)"s);  // Raw string literal for pattern
    std::string result = std::regex_replace(input, pattern, "Hi, Universe!");
    std::cout << result << std::endl;  // Outputs: Hi, Universe!
    return 0;
}
